-- Disposable synthetic normal operations; append synthetic_product.sql without COMMIT.
create function pg_temp.assert_equipment(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'equipment_assertion';end if;end$$;
create function pg_temp.deny_equipment(q text,c text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'equipment_expected_denial';end$$;
create temporary table saved_equipment(op text,inp jsonb,receipt jsonb);grant all on saved_equipment to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub',md5('density.actor.1.1')::uuid::text,true);
do $$declare w uuid:=md5('density.workspace.1')::uuid;c jsonb;o jsonb;con jsonb;s jsonb;term jsonb;i jsonb;e jsonb;r jsonb;old jsonb;n jsonb;begin
 c:=public.product_v1_customer_create(w,jsonb_build_object('command_id',gen_random_uuid(),'account_kind','legal_entity','legal_name','Synthetic Equipment Customer'));
 o:=public.catalog_v1_command(w,'operator.create',jsonb_build_object('command_id',gen_random_uuid(),'code','synthetic_equipment_operator','display_name','Synthetic Equipment Operator'));
 con:=public.portfolio_v1_contract_create_manual(w,jsonb_build_object('command_id',gen_random_uuid(),'customer_id',c->>'id','operator_id',o->>'id','plan_version_id',null,'start_date','2026-01-01'));
 s:=public.portfolio_v1_service_create_manual(w,jsonb_build_object('command_id',gen_random_uuid(),'contract_id',con->>'id','plan_version_id',null,'service_kind','fiber','display_name','Synthetic Equipment Fiber'));
 term:=public.portfolio_v1_permanence_create_manual(w,jsonb_build_object('command_id',gen_random_uuid(),'contract_id',con->>'id','service_id',s->>'id','commitment_kind','device','starts_on','2026-01-01','ends_on','2027-01-01','reason_code','manual_device'));
 i:=jsonb_build_object('command_id',gen_random_uuid(),'customer_id',c->>'id','contract_id',con->>'id','service_id',s->>'id','line_id',null,'commitment_id',term->>'id','kind','router','manufacturer','Synthetic Maker Must Not Audit','model','Synthetic Router Original','commercial_description','Synthetic Commercial Device','purchased_on','2026-01-01','assigned_on',null);
 e:=public.equipment_v1_command(w,'equipment.create',i);insert into saved_equipment values('equipment.create',i,e);perform pg_temp.assert_equipment(e->>'status'='prepared'and e=public.equipment_v1_command(w,'equipment.create',i));
 perform pg_temp.deny_equipment(format('select public.equipment_v1_command(%L,%L,%L)',w,'equipment.create',(i||jsonb_build_object('command_id',gen_random_uuid(),'customer_id',md5('density.customer.1.1')::uuid))::text),'P0002');
 perform pg_temp.deny_equipment(format('select public.equipment_v1_command(%L,%L,%L)',w,'equipment.create',(i||jsonb_build_object('command_id',gen_random_uuid(),'kind','mobile_terminal'))::text),'22023');
 i:=jsonb_build_object('command_id',gen_random_uuid(),'id',e->>'id','expected_version',1,'event_on','2026-01-01');r:=public.equipment_v1_command(w,'equipment.assign',i);insert into saved_equipment values('equipment.assign',i,r);perform pg_temp.assert_equipment(r->>'status'='assigned'and r->>'version'='2');
 perform pg_temp.deny_equipment(format('select public.equipment_v1_command(%L,%L,%L)',w,'equipment.assign',(i||jsonb_build_object('command_id',gen_random_uuid()))::text),'40001');
 i:=i||jsonb_build_object('command_id',gen_random_uuid(),'expected_version',2,'event_on','2026-01-02');r:=public.equipment_v1_command(w,'equipment.return',i);insert into saved_equipment values('equipment.return',i,r);perform pg_temp.assert_equipment(r->>'status'='returned'and r->>'version'='3');
 r:=public.equipment_v1_query(w,'equipment.get',jsonb_build_object('id',e->>'id'));perform pg_temp.assert_equipment(r->'record'->>'returned_on'='2026-01-02'and r->'record'->>'model'='Synthetic Router Original'and not(r->'record')?'serial');
 i:=jsonb_build_object('command_id',gen_random_uuid(),'customer_id',c->>'id','contract_id',con->>'id','service_id',s->>'id','line_id',null,'commitment_id',term->>'id','kind','router','manufacturer','Synthetic Maker','model','Synthetic Replace Original','commercial_description',null,'purchased_on','2026-01-01','assigned_on','2026-01-01');old:=public.equipment_v1_command(w,'equipment.create',i);
 i:=jsonb_build_object('command_id',gen_random_uuid(),'id',old->>'id','expected_version',1,'event_on','2026-01-03','manufacturer','Synthetic New Maker','model','Synthetic Replacement Router','commercial_description',null,'purchased_on','2026-01-02','commitment_id',null);r:=public.equipment_v1_command(w,'equipment.replace',i);insert into saved_equipment values('equipment.replace',i,r);perform pg_temp.assert_equipment(r->>'status'='replaced'and r->>'version'='2'and r->>'replacement_version'='1');
 n:=public.equipment_v1_query(w,'equipment.get',jsonb_build_object('id',r->>'replacement_id'));perform pg_temp.assert_equipment(n->'record'->>'replaces_equipment_id'=old->>'id'and n->'record'->>'assigned_on'='2026-01-03'and n->'record'->>'model'='Synthetic Replacement Router'and n->'record'->'commitment_id'='null'::jsonb);
 n:=public.equipment_v1_query(w,'equipment.get',jsonb_build_object('id',old->>'id'));perform pg_temp.assert_equipment(n->'record'->>'model'='Synthetic Replace Original'and n->'record'->>'commitment_id'=term->>'id');
 i:=jsonb_build_object('command_id',gen_random_uuid(),'customer_id',c->>'id','contract_id',null,'service_id',null,'line_id',null,'commitment_id',null,'kind','ont','manufacturer','Synthetic Maker','model','Synthetic Reserved ONT','commercial_description',null,'purchased_on',null,'assigned_on',null);n:=public.equipment_v1_command(w,'equipment.create',i);
 i:=jsonb_build_object('command_id',gen_random_uuid(),'id',n->>'id','expected_version',1,'event_on','2026-01-03');r:=public.equipment_v1_command(w,'equipment.cancel',i);insert into saved_equipment values('equipment.cancel',i,r);perform pg_temp.assert_equipment(r->>'status'='cancelled');
 n:=public.equipment_v1_query(w,'equipment.list',jsonb_build_object('customer_id',c->>'id','limit',1));perform pg_temp.assert_equipment(jsonb_array_length(n->'items')=1 and n->'next_id'<>'null'::jsonb);
 n:=public.equipment_v1_query(w,'equipment.history',jsonb_build_object('id',old->>'id','limit',1));perform pg_temp.assert_equipment(n->'items'->0->>'version'='1'and n->>'next_version'='1');n:=public.equipment_v1_query(w,'equipment.history',jsonb_build_object('id',old->>'id','after_version',1));perform pg_temp.assert_equipment(n->'items'->0->>'status'='replaced'and jsonb_array_length(n->'items')=1);
end$$;
set constraints all immediate;
do $$declare x record;begin for x in select *from saved_equipment loop perform pg_temp.assert_equipment(x.receipt=public.equipment_v1_command(md5('density.workspace.1')::uuid,x.op,x.inp));end loop;end$$;
reset role;
select pg_temp.assert_equipment(not exists(select 1 from public.product_audit_events where to_jsonb(product_audit_events)::text like'%Synthetic Maker Must Not Audit%'));
update public.workspace_members set role='viewer'where workspace_id=md5('density.workspace.1')::uuid and user_id=md5('density.actor.1.3')::uuid;
set local role authenticated;select set_config('request.jwt.claim.sub',md5('density.actor.1.3')::uuid::text,true);
do $$declare x record;r jsonb;begin for x in select *from saved_equipment loop perform pg_temp.deny_equipment(format('select public.equipment_v1_command(%L,%L,%L)',md5('density.workspace.1')::uuid,x.op,x.inp::text),'42501');end loop;r:=public.equipment_v1_query(md5('density.workspace.1')::uuid,'equipment.get',jsonb_build_object('id',(select receipt->>'id'from saved_equipment where op='equipment.create')));perform pg_temp.assert_equipment(r->'record'->>'status'='returned');end$$;
reset role;update public.workspace_members set status='suspended'where workspace_id=md5('density.workspace.1')::uuid and user_id=md5('density.actor.1.1')::uuid;
set local role authenticated;select set_config('request.jwt.claim.sub',md5('density.actor.1.1')::uuid::text,true);
do $$declare x record;begin for x in select *from saved_equipment loop perform pg_temp.deny_equipment(format('select public.equipment_v1_command(%L,%L,%L)',md5('density.workspace.1')::uuid,x.op,x.inp::text),'42501');end loop;end$$;
reset role;rollback;
